const LENA_AI_DESCRIPTION_TRANSLATIONS: Partial<Record<Locale, string>> = {
  de: 'LenaAI ist eine künstliche Intelligenz, die als digitaler Frachtdisponent arbeitet. Sie unterstützt Speditionen bei der Koordination von Ladungen, Routen, Statusmeldungen und Buchungen und gibt Fahrern schnelle, klare Antworten zu ihren Aufträgen – immer auf Grundlage der neuesten Daten, auf die sie zugreifen dürfen.',
  pl: 'LenaAI to sztuczna inteligencja działająca jako cyfrowy dyspozytor transportu. Pomaga spedytorom koordynować ładunki, trasy, statusy i rezerwacje, a kierowcom udziela szybkich i jasnych odpowiedzi dotyczących ich zleceń — zawsze na podstawie najnowszych danych, do których mają dostęp.',
  ro: 'LenaAI este o inteligență artificială creată pentru a lucra ca dispecer digital de transport. Ajută expeditorii să coordoneze încărcăturile, rutele, statusurile și rezervările, iar șoferilor le oferă răspunsuri rapide și clare despre cursele lor — întotdeauna pe baza celor mai recente date la care au acces.',
  nl: 'LenaAI is kunstmatige intelligentie die werkt als digitale transportplanner. Ze helpt expediteurs met het coördineren van ladingen, routes, statussen en boekingen en geeft chauffeurs snelle, duidelijke antwoorden over hun opdrachten — altijd op basis van de nieuwste gegevens waartoe zij toegang hebben.',
  fr: 'LenaAI est une intelligence artificielle conçue pour agir comme un répartiteur de fret numérique. Elle aide les transitaires à coordonner les chargements, les itinéraires, les statuts et les réservations, tout en donnant aux conducteurs des réponses rapides et claires sur leurs missions — toujours à partir des données les plus récentes auxquelles ils sont autorisés à accéder.',
  it: 'LenaAI è un’intelligenza artificiale progettata per operare come dispatcher digitale dei trasporti. Aiuta gli spedizionieri a coordinare carichi, rotte, stati e prenotazioni e offre agli autisti risposte rapide e chiare sui loro incarichi, sempre basate sui dati più recenti a cui sono autorizzati ad accedere.',
  zh: 'LenaAI 是一款充当数字货运调度员的人工智能。它帮助货运代理协调货物、路线、状态和预订，同时根据用户有权查看的最新数据，为司机快速、清晰地解答当前运输任务。',
  es: 'LenaAI es una inteligencia artificial creada para trabajar como despachador digital de transporte. Ayuda a los transitarios a coordinar cargas, rutas, estados y reservas, y ofrece a los conductores respuestas rápidas y claras sobre sus servicios, siempre basadas en los datos más recientes a los que están autorizados a acceder.',
  sr: 'LenaAI je veštačka inteligencija koja radi kao digitalni dispečer. Špedicijama pomaže u organizaciji tereta, ruta, statusa i rezervacija, a vozačima daje brze i jasne odgovore o poslu koji ih čeka — uvek na osnovu najnovijih podataka kojima imaju pristup.',
  sv: 'LenaAI är artificiell intelligens som fungerar som en digital transportledare. Den hjälper speditörer att samordna laster, rutter, statusar och bokningar och ger förare snabba, tydliga svar om deras uppdrag — alltid baserat på de senaste uppgifterna de har behörighet att se.',
  ar: 'LenaAI هو نظام ذكاء اصطناعي يعمل كمُنسّق رقمي لعمليات الشحن. يساعد شركات الشحن على تنسيق الحمولات والمسارات والحالات والحجوزات، ويمنح السائقين إجابات سريعة وواضحة حول مهامهم، اعتمادًا دائمًا على أحدث البيانات المصرح لهم بالوصول إليها.',
  pt: 'LenaAI é uma inteligência artificial criada para atuar como despachante digital de transporte. Ajuda os transitários a coordenar cargas, rotas, estados e reservas e oferece aos motoristas respostas rápidas e claras sobre os seus serviços — sempre com base nos dados mais recentes a que estão autorizados a aceder.',
};

for (const [localeKey, description] of Object.entries(LENA_AI_DESCRIPTION_TRANSLATIONS)) {
  UI[localeKey as Locale]['landing.aiDispatcher.description'] = description;
}

