for (const [locale, overrides] of Object.entries(EXTENDED_UI)) {
  Object.assign(UI[locale as Locale], overrides);
}

for (const [locale, overrides] of Object.entries(SUPPLEMENTAL_UI)) {
  Object.assign(UI[locale as Locale], overrides);
}

const makeDatePicker = (
  weekdaysShort: CustomLocale['weekdays']['shorthand'],
  weekdaysLong: CustomLocale['weekdays']['longhand'],
  monthsShort: CustomLocale['months']['shorthand'],
  monthsLong: CustomLocale['months']['longhand'],
  rangeSeparator: string,
  weekAbbreviation: string,
  scrollTitle: string,
  toggleTitle: string
) => ({
  weekdays: { shorthand: weekdaysShort, longhand: weekdaysLong },
  months: { shorthand: monthsShort, longhand: monthsLong },
  firstDayOfWeek: 1,
  rangeSeparator,
  weekAbbreviation,
  scrollTitle,
  toggleTitle,
});

