  'Manage triggers, security rules, and smart route automations from one place.': { bs: 'Upravljaj triggerima, sigurnosnim pravilima i pametnim automatizacijama ruta sa jednog mjesta.', de: 'Verwalte Trigger, Sicherheitsregeln und smarte Routenautomatisierungen an einem Ort.', pl: 'Zarzadzaj triggerami, zasadami bezpieczenstwa i inteligentnymi automatyzacjami tras z jednego miejsca.', ro: 'Gestioneaza trigger-ele, regulile de securitate si automatizarile inteligente de ruta dintr-un singur loc.', nl: 'Beheer triggers, beveiligingsregels en slimme route-automatiseringen vanaf een plek.', fr: 'Gerez les declencheurs, les regles de securite et les automatisations intelligentes de route depuis un seul endroit.', it: 'Gestisci trigger, regole di sicurezza e automazioni intelligenti dei percorsi da un unico posto.', zh: '在一个地方管理触发器、安全规则和智能路线自动化。', es: 'Gestiona disparadores, reglas de seguridad y automatizaciones inteligentes de rutas desde un solo lugar.', sr: 'Upravljaj triggerima, sigurnosnim pravilima i pametnim automatizacijama ruta sa jednog mjesta.', sv: 'Hantera triggers, sakerhetsregler och smarta ruttautomationer fran ett stalle.', ar: 'أدر المشغلات وقواعد الأمان وأتمتة المسارات الذكية من مكان واحد.', pt: 'Gira gatilhos, regras de seguranca e automatizacoes inteligentes de rotas num so lugar.' },
