  'Truck PT-19 reached Vienna checkpoint.': { bs: 'Kamion PT-19 stigao je na kontrolnu tačku u Beču.', de: 'LKW PT-19 hat den Kontrollpunkt in Wien erreicht.', pl: 'Ciezarowka PT-19 dotarla do punktu kontrolnego w Wiedniu.', ro: 'Camionul PT-19 a ajuns la punctul de control din Viena.', nl: 'Truck PT-19 heeft het controlepunt in Wenen bereikt.', fr: 'Le camion PT-19 a atteint le point de controle de Vienne.', it: 'Il camion PT-19 ha raggiunto il checkpoint di Vienna.', zh: '卡车 PT-19 已到达维也纳检查点。', es: 'El camion PT-19 llego al punto de control de Viena.', sr: 'Kamion PT-19 je stigao do kontrolne tacke u Becu.', sv: 'Lastbil PT-19 har natt kontrollpunkten i Wien.', ar: 'وصلت الشاحنة PT-19 الى نقطة التفتيش في فيينا.', pt: 'O camiao PT-19 chegou ao checkpoint de Viena.' },
  'Received. Updating ETA for customer now.': { bs: 'Primljeno. Sada ažuriram ETA za korisnika.', de: 'Verstanden. Ich aktualisiere jetzt die ETA fuer den Kunden.', pl: 'Otrzymano. Aktualizuje teraz ETA dla klienta.', ro: 'Primit. Actualizez acum ETA pentru client.', nl: 'Ontvangen. Ik werk nu de ETA voor de klant bij.', fr: 'Recu. Je mets a jour l ETA pour le client maintenant.', it: 'Ricevuto. Sto aggiornando ora l ETA per il cliente.', zh: '收到。现在正在为客户更新 ETA。', es: 'Recibido. Estoy actualizando ahora la ETA para el cliente.', sr: 'Primljeno. Sada azuriram ETA za klijenta.', sv: 'Mottaget. Uppdaterar nu ETA for kunden.', ar: 'تم الاستلام. اقوم الآن بتحديث وقت الوصول المتوقع للعميل.', pt: 'Recebido. Estou a atualizar agora o ETA para o cliente.' },
  'Please share updated ETA once AI route sync completes.': { bs: 'Molimo podijelite ažurirani ETA kada AI sinhronizacija rute završi.', de: 'Bitte teilen Sie die aktualisierte ETA, sobald die KI-Routensynchronisierung abgeschlossen ist.', pl: 'Prosze udostepnic zaktualizowane ETA po zakonczeniu synchronizacji trasy AI.', ro: 'Te rugam sa trimiti ETA actualizat dupa finalizarea sincronizarii rutei AI.', nl: 'Deel de bijgewerkte ETA zodra de AI-routesynchronisatie is voltooid.', fr: 'Veuillez partager l ETA mise a jour une fois la synchronisation AI de l itineraire terminee.', it: 'Condividi l ETA aggiornato una volta completata la sincronizzazione AI del percorso.', zh: 'AI 路线同步完成后，请分享更新后的 ETA。', es: 'Comparte la ETA actualizada una vez que termine la sincronizacion AI de la ruta.', sr: 'Molimo podelite azurirani ETA kada se zavrsi AI sinhronizacija rute.', sv: 'Dela uppdaterad ETA nar AI-ruttsynken ar klar.', ar: 'يرجى مشاركة وقت الوصول المتوقع المحدث بمجرد اكتمال مزامنة المسار بالذكاء الاصطناعي.', pt: 'Partilhe o ETA atualizado assim que a sincronizacao AI da rota estiver concluida.' },
  'Update ETA and send status to customer.': { bs: 'Azuriraj ETA i posalji status klijentu.', de: 'ETA aktualisieren und Status an den Kunden senden.', pl: 'Zaktualizuj ETA i wyslij status klientowi.', ro: 'Actualizeaza ETA si trimite statusul clientului.', nl: 'Werk de ETA bij en stuur de status naar de klant.', fr: 'Mettez a jour l ETA et envoyez le statut au client.', it: 'Aggiorna l ETA e invia lo stato al cliente.', zh: '更新 ETA 并向客户发送状态。', es: 'Actualiza el ETA y envia el estado al cliente.', sr: 'Azuriraj ETA i posalji status klijentu.', sv: 'Uppdatera ETA och skicka status till kunden.', ar: 'حدّث وقت الوصول وأرسل الحالة إلى العميل.', pt: 'Atualize o ETA e envie o estado ao cliente.' },
  'Maintenance alert: DE-992-AB due tomorrow.': { bs: 'Upozorenje za održavanje: DE-992-AB je na redu sutra.', de: 'Wartungswarnung: DE-992-AB ist morgen faellig.', pl: 'Alert serwisowy: DE-992-AB termin jutro.', ro: 'Alerta mentenanta: DE-992-AB este programat pentru maine.', nl: 'Onderhoudsmelding: DE-992-AB is morgen aan de beurt.', fr: 'Alerte maintenance : DE-992-AB est prevu pour demain.', it: 'Avviso manutenzione: DE-992-AB in scadenza domani.', zh: '维护提醒：DE-992-AB 将于明天到期。', es: 'Alerta de mantenimiento: DE-992-AB vence manana.', sr: 'Upozorenje za odrzavanje: DE-992-AB je na redu sutra.', sv: 'Underhallsvarning: DE-992-AB ska servas i morgon.', ar: 'تنبيه صيانة: DE-992-AB مستحق غدا.', pt: 'Alerta de manutencao: DE-992-AB vence amanha.' },
