  'Return window is 14 days. Pickup is available tomorrow between 09:00-13:00.': { bs: 'Rok za povrat je 14 dana. Preuzimanje je dostupno sutra u periodu 09:00-13:00.', de: 'Rueckgabefrist ist 14 Tage. Abholung morgen zwischen 09:00-13:00 verfuegbar.', pl: 'Okno zwrotu wynosi 14 dni. Odbior jest dostepny jutro miedzy 09:00 a 13:00.', ro: 'Perioada de retur este de 14 zile. Ridicarea este disponibila maine intre 09:00-13:00.', nl: 'De retourtermijn is 14 dagen. Ophalen is morgen mogelijk tussen 09:00-13:00.', fr: 'La periode de retour est de 14 jours. L enlèvement est disponible demain entre 09:00 et 13:00.', it: 'La finestra di reso e di 14 giorni. Il ritiro e disponibile domani tra le 09:00 e le 13:00.', zh: '退货期限为 14 天。可于明天 09:00-13:00 上门取件。', es: 'La ventana de devolucion es de 14 dias. La recogida esta disponible manana entre 09:00-13:00.', sr: 'Rok za povrat je 14 dana. Preuzimanje je dostupno sutra u periodu 09:00-13:00.', sv: 'Returperioden ar 14 dagar. Hamtning ar tillganglig imorgon mellan 09:00-13:00.', ar: 'فترة الإرجاع 14 يوماً. الاستلام متاح غداً بين 09:00 و13:00.', pt: 'A janela de devolucao e de 14 dias. A recolha esta disponivel amanha entre as 09:00 e as 13:00.' },
