  'Recalculates every 3 min using live road events and fleet constraints.': { bs: 'Preracunava se svake 3 min koristeci dogadjaje na putu uzivo i ogranicenja flote.', de: 'Berechnet sich alle 3 min neu anhand von Live-Strassenereignissen und Flotteneinschrankungen.', pl: 'Przelicza co 3 minuty, wykorzystujac zdarzenia drogowe na zywo i ograniczenia floty.', ro: 'Recalculeaza la fiecare 3 minute folosind evenimente rutiere live si restrictiile flotei.', nl: 'Herberekent elke 3 minuten op basis van live weggebeurtenissen en vlootbeperkingen.', fr: 'Recalcule toutes les 3 minutes a partir des evenements routiers en direct et des contraintes de flotte.', it: 'Ricalcola ogni 3 minuti usando eventi stradali in tempo reale e vincoli della flotta.', zh: '每 3 分钟根据实时道路事件和车队限制重新计算。', es: 'Recalcula cada 3 min usando eventos viales en tiempo real y restricciones de la flota.', sr: 'Preracunava svaka 3 minuta koristeci dogadjaje na putu uzivo i ogranicenja flote.', sv: 'Raknar om var tredje minut med live vaghandelser och flottbegransningar.', ar: 'يعيد الحساب كل 3 دقائق باستخدام احداث الطريق المباشرة وقيود الاسطول.', pt: 'Recalcula a cada 3 min usando eventos rodoviarios em tempo real e restricoes da frota.' },
