for (const [key, value] of Object.entries(TRIPLET_ZH_OVERRIDES)) {
  TRIPLET_TRANSLATIONS[key] = { ...(TRIPLET_TRANSLATIONS[key] || {}), zh: value };
}

const REVERSE_UI_KEY_BY_EN: Record<string, string> = Object.fromEntries(
  Object.entries(UI_EN).map(([key, value]) => [value, key]),
);

const UI_FROM_TRIPLET: Record<string, string> = {
  'routeCalc.bestFitFor': 'Best fit for',
  'routeCalc.priority': 'priority',
  'routeCalc.high': 'High',
  'routeCalc.optimized': 'Optimized',
  'routeCalc.strong': 'Strong',
  'routeCalc.recalculatesNote': 'Recalculates every 3 min using live road events and fleet constraints.',
  'chat.suggestionEtaUpdates': 'Suggestion: Send automatic ETA updates to all clients on this route.',
  'common.security': 'Security',
  'chat.encryptionEnabled': 'End-to-end encryption enabled.',
  'chat.channelStatus': 'Channel Status',
  'chat.newMessage': 'New Message',
  'common.analytics': 'Analytics',
  'login.close': 'Close login',
  'setup.driverType': 'Driver Type',
  'setup.driverTypeDesc': 'Are you an independent driver or a company?',
  'setup.privateDriver': 'Private Driver',
  'setup.logisticsCompany': 'Logistics Company',
  'setup.vehicleDetails': 'Vehicle Details',
  'setup.vehicleDetailsDesc': 'Provide your vehicle details',
  'setup.make': 'Make',
  'setup.model': 'Model',
  'setup.year': 'Year',
  'setup.close': 'Close setup',
};

// Most TRIPLET_TRANSLATIONS entries key themselves by their own literal English text (e.g.
// 'Safety Score': {...}), so using the key as the English value is correct for those. But a few
// entries (e.g. 'Lena welcome general') use a short semantic key instead, with the real English
// text only in their `en` field - defaulting to the key for those would silently overwrite the
// correct English value with the raw key name. Prefer the explicit `en` field when present.
for (const [englishValue, translations] of Object.entries(TRIPLET_TRANSLATIONS)) {
  UI.en[englishValue] = translations.en ?? englishValue;
  for (const localeKey of Object.keys(UI) as Locale[]) {
    if (localeKey === 'en') continue;
    const translated = translations[localeKey];
    if (translated) {
      UI[localeKey][englishValue] = translated;
    }
  }
}

for (const [key, englishValue] of Object.entries(UI_FROM_TRIPLET)) {
  UI.en[key] = englishValue;
  for (const localeKey of Object.keys(UI) as Locale[]) {
    if (localeKey === 'en') continue;
    const translated = TRIPLET_TRANSLATIONS[englishValue]?.[localeKey];
    if (translated) {
      UI[localeKey][key] = translated;
    }
  }
}

const translateValue = (lang: Language, value: string) => {
  const active = (lang || 'en') as Locale;
  return VALUE_TRANSLATIONS[value]?.[active] || value;
};

export const translateTriplet = (lang: Language, en: string, bs: string, de: string) => {
  if (lang === 'bs') return bs;
  if (lang === 'de') return de;
  const active = (lang || 'en') as Locale;
  const tripletHit = TRIPLET_TRANSLATIONS[en]?.[active];
  if (tripletHit) return tripletHit;
  const uiKey = REVERSE_UI_KEY_BY_EN[en];
  if (uiKey) return locale(lang)[uiKey] || UI.en[uiKey] || en;
  return en;
};

const locale = (lang: Language) => UI[(lang || 'en') as Locale] || UI.en;
const replaceBrand = (value: string) => value.replace(/smartfreight\.ai/gi, 'Freightbook.ai').replace(/smartfreight/gi, 'Freightbook.ai');

export const ui = (lang: Language, key: string, fallback: string) => {
  const active = (lang || 'en') as Locale;
  const localized = locale(lang)[key];
  if (localized) return replaceBrand(localized);

  const englishValue = UI.en[key];
  if (englishValue) return replaceBrand(englishValue);

  const reverseUiKey = REVERSE_UI_KEY_BY_EN[fallback];
  if (reverseUiKey) {
    return replaceBrand(locale(lang)[reverseUiKey] || UI.en[reverseUiKey] || fallback);
  }

  return replaceBrand(TRIPLET_TRANSLATIONS[fallback]?.[active] || TRIPLET_TRANSLATIONS[key]?.[active] || fallback);
};

export const flatpickrI18n = (lang: Language) =>
  DATE_PICKER_I18N[(lang || 'en') as Locale] || DATE_PICKER_I18N.en;

export const trLoadStatus = (lang: Language, value: string) => translateValue(lang, value);

export const trPackageStatus = (lang: Language, value: string) => translateValue(lang, value);

export const trFuelType = (lang: Language, value: string) => translateValue(lang, value);

export const trGoodsType = (lang: Language, value: string) => translateValue(lang, value);

export const trPaymentTerms = (lang: Language, value: string) => translateValue(lang, value);

export const trVehicleStatus = (lang: Language, value: string) => translateValue(lang, value);
